'use strict';

// PURE_JS_ONLY_NO_NATIVE: actual prototype methods, generated bytes only.
// No Machine construction, CPU, guest program, VM, WASM or original media.
const { test } = require('node:test');
const assert = require('node:assert/strict');
const { Machine } = require('../tools/toyvm/dos');

function machine() {
  const m = Object.create(Machine.prototype);
  Object.assign(m, { mem: new Uint8Array(0x100000), curPsp: 0x50,
    currentDrive: 2, currentDirectory: '', driveDirectories: new Map(),
    floppyVolumes: new Map(), isoVolumes: new Map(), tempFiles: new Map(),
    virtualDirectories: new Set(), fileRoot: null, files: new Map(), fileNext: 5,
    filesCreated: [], filesOpened: [], filesMissed: [], dta: 0x4000,
    directorySearches: new Map(), directorySearchIds: new Map(), directorySearchSerial: 0,
    lastError: 77 });
  return m;
}
function registers(ax = 0x0d00, flags = 0xad7) {
  const v = { ax, bx: 0x9753, cx: 0x1234, dx: 0x6486, ds: 0, es: 0x123,
    si: 0x4321, di: 0x5678, ss: 0x200, sp: 0xff00, flags };
  return { v, get: k => v[k], set: (k, n) => { v[k] = n; },
    setResultCf: b => { v.flags = (v.flags & ~1) | +b; } };
}
function reset(m, r = registers()) {
  const before = { ...r.v };
  assert.equal(m.int21Call(0x0d, r.v.ax & 255, r), true);
  assert.deepEqual(r.v, before);
  assert.equal(m.lastError, 77);
}

test('disk reset is handled and preserves registers/flags for both incoming CF states', () => {
  const m = machine();
  for (const flags of [0xad6, 0xad7]) reset(m, registers(0x0d00, flags));
  assert(!m.tempFiles.size); assert(!m.files.size);
});

test('reset retains immediate overlay writes, open handles, positions, metadata and directories', () => {
  const m = machine();
  m.virtualDirectories.add('example');
  const h = m.createFile('C:\\EXAMPLE\\DATA.BIN'), f = m.files.get(h);
  assert(h >= 5);
  m.mem.set([11, 22, 33, 44], 0x3000); m.writeFile(f, 0x3000, 4);
  f.rec.date = 0x4567; f.rec.time = 0x1234; f.rec.attributes = 0x21;
  const reader = m.openFile('C:\\EXAMPLE\\DATA.BIN', 'r');
  m.files.get(reader).pos = 2;
  const files = [...m.files], rec = f.rec, directories = m.virtualDirectories;
  m.currentDirectory = 'example'; m.driveDirectories.set(2, 'example');
  reset(m);
  assert.deepEqual([...m.files], files); assert.equal(f.rec, rec); assert.equal(f.pos, 4);
  assert.equal(m.files.get(reader).pos, 2); assert.equal(m.virtualDirectories, directories);
  assert.equal(m.currentDrive, 2); assert.equal(m.currentDirectory, 'example');
  assert.equal(m.driveDirectories.get(2), 'example');
  assert.deepEqual(m.readWholeFile('DATA.BIN'), Buffer.from([11, 22, 33, 44]));
  assert.deepEqual([rec.date, rec.time, rec.attributes], [0x4567, 0x1234, 0x21]);
});

test('reset preserves DTA and independent FCB continuation across an unfinished search', () => {
  const m = machine(), at = 0x6486;
  for (const name of ['one.bin', 'two.bin']) m.tempFiles.set(name, { len: 0, attributes: 0x20 });
  m.mem[at] = 255; m.mem[at + 6] = 0;
  m.mem.set(Buffer.from('???????????'), at + 8);
  const r = registers(0x1103);
  assert.equal(m.int21Call(0x11, 3, r), true); assert.equal(r.v.ax & 255, 0);
  const fcb = m.mem.slice(at, at + 44), result = m.mem.slice(m.dta, m.dta + 40), searches = m.fcbSearches;
  reset(m);
  assert.equal(m.dta, 0x4000); assert.deepEqual(m.mem.slice(at, at + 44), fcb);
  assert.deepEqual(m.mem.slice(m.dta, m.dta + 40), result); assert.equal(m.fcbSearches, searches);
  r.v.ax = 0x1203;
  assert.equal(m.int21Call(0x12, 3, r), true); assert.equal(r.v.ax & 255, 0);
  assert.equal(Buffer.from(m.mem.slice(m.dta + 8, m.dta + 19)).toString(), 'TWO     BIN');
});
